import { EChartsType } from '@/src/echarts';
import { EChartsOption } from '@/src/export/option';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';
import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';

/**
 * The y coord of every split line of the first yAxis, sorted ascending.
 */
function getSplitLineYCoords(chart: EChartsType): number[] {
    const coords: number[] = [];
    getGraphicElements(chart, 'yAxis', 0).forEach(function (el) {
        // The split lines are the only `Line` elements that go across the grid,
        // the axis ticks are much shorter.
        if (el.type === 'line' && (el as any).anid && /^line_/.test((el as any).anid)) {
            coords.push((el as any).shape.y1);
        }
    });
    return coords.sort(function (a, b) {
        return a - b;
    });
}

function makeOption(splitLine: object): EChartsOption {
    return {
        animation: false,
        grid: { left: 40, right: 20, top: 20, bottom: 30 },
        xAxis: { type: 'category', data: ['a', 'b', 'c', 'd'] },
        yAxis: {
            type: 'value',
            min: 0,
            max: 400,
            interval: 100,
            splitLine: splitLine
        },
        series: [{ type: 'line', data: [100, 200, 300, 400] }]
    } as EChartsOption;
}

describe('component/axis/splitLineMinMax', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 400, height: 300 });
    });
    afterEach(function () {
        removeChart(chart);
    });

    it('should draw all of the split lines by default', function () {
        chart.setOption(makeOption({ show: true }));

        const coords = getSplitLineYCoords(chart);
        // 0, 100, 200, 300, 400
        expect(coords.length).toEqual(5);

        const axis = (getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel).axis;
        const extent = axis.getExtent();
        const min = Math.min(extent[0], extent[1]);
        const max = Math.max(extent[0], extent[1]);
        expect(coords[0]).toBeCloseTo(min, 4);
        expect(coords[coords.length - 1]).toBeCloseTo(max, 4);
    });

    it('should not draw the line at the min value when showMinLine is false', function () {
        chart.setOption(makeOption({ show: true, showMinLine: false }));

        const coords = getSplitLineYCoords(chart);
        expect(coords.length).toEqual(4);

        const axis = (getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel).axis;
        // The min of a normal yAxis is at the bottom, which is the greater coord.
        const minCoord = axis.toGlobalCoord(axis.dataToCoord(0));
        const maxCoord = axis.toGlobalCoord(axis.dataToCoord(400));
        coords.forEach(function (coord) {
            expect(Math.abs(coord - minCoord)).toBeGreaterThan(1);
        });
        expect(coords[0]).toBeCloseTo(maxCoord, 4);
    });

    it('should not draw the line at the max value when showMaxLine is false', function () {
        chart.setOption(makeOption({ show: true, showMaxLine: false }));

        const coords = getSplitLineYCoords(chart);
        expect(coords.length).toEqual(4);

        const axis = (getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel).axis;
        const minCoord = axis.toGlobalCoord(axis.dataToCoord(0));
        const maxCoord = axis.toGlobalCoord(axis.dataToCoord(400));
        coords.forEach(function (coord) {
            expect(Math.abs(coord - maxCoord)).toBeGreaterThan(1);
        });
        expect(coords[coords.length - 1]).toBeCloseTo(minCoord, 4);
    });

    it('should support hiding both of the boundary lines', function () {
        chart.setOption(makeOption({ show: true, showMinLine: false, showMaxLine: false }));

        const coords = getSplitLineYCoords(chart);
        // Only 100, 200, 300 are left.
        expect(coords.length).toEqual(3);
    });

    it('should hide the boundary lines of an inversed axis by value, not by position', function () {
        const option = makeOption({ show: true, showMinLine: false });
        (option.yAxis as any).inverse = true;
        chart.setOption(option);

        const coords = getSplitLineYCoords(chart);
        expect(coords.length).toEqual(4);

        const axis = (getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel).axis;
        // The min is at the top when the axis is inversed.
        const minCoord = axis.toGlobalCoord(axis.dataToCoord(0));
        coords.forEach(function (coord) {
            expect(Math.abs(coord - minCoord)).toBeGreaterThan(1);
        });
    });

    it('should keep the boundary lines when the options are set to true', function () {
        chart.setOption(makeOption({ show: true, showMinLine: true, showMaxLine: true }));
        expect(getSplitLineYCoords(chart).length).toEqual(5);
    });

    it('should work on a category axis with boundaryGap', function () {
        chart.setOption({
            animation: false,
            grid: { left: 40, right: 20, top: 20, bottom: 30 },
            xAxis: {
                type: 'category',
                data: ['a', 'b', 'c', 'd'],
                splitLine: { show: true, showMinLine: false, showMaxLine: false }
            },
            yAxis: { type: 'value' },
            series: [{ type: 'bar', data: [1, 2, 3, 4] }]
        } as EChartsOption);

        const coords: number[] = [];
        getGraphicElements(chart, 'xAxis', 0).forEach(function (el) {
            if (el.type === 'line' && (el as any).anid && /^line_/.test((el as any).anid)) {
                coords.push((el as any).shape.x1);
            }
        });
        // 5 band boundaries, of which the two at the ends are hidden.
        expect(coords.length).toEqual(3);
    });
});

