            series: [{ type: 'bar', data: [1, 2, 3, 4] }]
        } as EChartsOption);

        const coords: number[] = [];
        getGraphicElements(chart, 'xAxis', 0).forEach(function (el) {
            if (el.type === 'line' && (el as any).anid && /^line_/.test((el as any).anid)) {
                coords.push((el as any).shape.x1);
            }
        });
        // 5 band boundaries, of which the two at the ends are hidden.
        expect(coords.length).toEqual(3);
    });
});

