    api: ExtensionAPI,
    step: LineSeriesOption['step'],
    valueOrigin: LineSeriesOption['areaStyle']['origin'],
    connectNulls: boolean
) {
    const polyline = this._polyline;
    const polygon = this._polygon;
    const seriesModel = data.hostModel;

    const diff = lineAnimationDiff(
        this._data, data,
        this._stackedOnPoints, stackedOnPoints,
        this._coordSys, coordSys,
        this._valueOrigin, valueOrigin
    );

    let current = diff.current;
    let stackedOnCurrent = diff.stackedOnCurrent;
    let next = diff.next;
    let stackedOnNext = diff.stackedOnNext;
    if (step) {
        // TODO If stacked series is not step
        // NOTE: `points` and `stackedOnPoints` must be turned into step points
        // together, so that they keep index aligned. See #20092
        const steppedCurrent = turnPointsIntoStep(
            diff.current, diff.stackedOnCurrent, coordSys, step, connectNulls
        );
        const steppedNext = turnPointsIntoStep(
            diff.next, diff.stackedOnNext, coordSys, step, connectNulls
        );
        current = steppedCurrent.points;
        stackedOnCurrent = steppedCurrent.stackedOnPoints;
        next = steppedNext.points;
        stackedOnNext = steppedNext.stackedOnPoints;
    }
    // Don't apply animation if diff is large.
    // For better result and avoid memory explosion problems like
    // https://github.com/apache/incubator-echarts/issues/12229
    if (getBoundingDiff(current, next) > 3000
        || (polygon && getBoundingDiff(stackedOnCurrent, stackedOnNext) > 3000)
    ) {
        polyline.stopAnimation();
        polyline.setShape({
            points: next
        });
        if (polygon) {
            polygon.stopAnimation();
            polygon.setShape({
                points: next,
                stackedOnPoints: stackedOnNext
            });
        }
        return;
    }

    (polyline.shape as any).__points = diff.current;
    polyline.shape.points = current;

    const target = {
        shape: {
            points: next
        }
    };
    // Also animate the original points.
    // If points reference is changed when turning into step line.
    if (diff.current !== current) {
        (target.shape as any).__points = diff.next;
    }

    // Stop previous animation.
    polyline.stopAnimation();
    graphic.updateProps(polyline, target, seriesModel);

    if (polygon) {
        polygon.setShape({

