        });
    });

    it('should keep the step points of the area base line aligned', function () {
        chart.setOption(makeOption({ data: [10, 20, 30, 40, 50], step: 'end', area: true }));

        const polygon = getPolyShape(chart, 'ec-polygon');
        const raw = getRawPoints(chart);
        expectSamePoints(polygon.points, makeExpectedStepPoints(raw, 'end'));
        // The base line is stepped the same way, so that both arrays are aligned.
        expect(polygon.stackedOnPoints.length).toEqual(polygon.points.length);
        for (let i = 0; i < polygon.points.length; i += 2) {
            expect(polygon.stackedOnPoints[i]).toBeCloseTo(polygon.points[i] as number, 2);
        }
    });

    it('should keep the null gaps of a step line', function () {
        chart.setOption(makeOption({ data: [10, null, 30, 40, null], step: 'start' }));

        const raw = getRawPoints(chart);
        const points = getPolyShape(chart, 'ec-polyline').points;
        // The null points are kept so that the gaps are still rendered.
        expectSamePoints(points, makeExpectedStepPoints(raw, 'start'));
        let nanCount = 0;
        for (let i = 0; i < points.length; i += 2) {
            isNaN(points[i + 1]) && nanCount++;
        }
        expect(nanCount).toBeGreaterThan(0);
    });

    it('should drop the null points of a step line when connectNulls', function () {
        chart.setOption(makeOption({
            data: [10, null, 30, 40, null], step: 'middle', area: true, connectNulls: true
        }));

        const raw = getRawPoints(chart);
        const polygon = getPolyShape(chart, 'ec-polygon');
        expectSamePoints(polygon.points, makeExpectedStepPoints(raw, 'middle', true));
        expectSamePoints(polygon.stackedOnPoints, makeExpectedStepPoints(
            getPolyShape(chart, 'ec-polygon') && (polygon as any).__rawStackedOn || raw, 'middle', true
        ).map(function (val, idx) {
            // Only the length and the base dim are compared here, the value dim
            // of the base line is the axis origin.
            return idx % 2 === 0 ? val : polygon.stackedOnPoints[idx];
        }));
        // 3 remaining points turn into 3 * 3 - 2 = 7 step points.
        expect(polygon.points.length).toEqual(14);
        for (let i = 0; i < polygon.points.length; i++) {
            expect(isNaN(polygon.points[i])).toBe(false);
            expect(isNaN(polygon.stackedOnPoints[i])).toBe(false);
        }
    });

    it('should handle a single data item and an empty series', function () {
        expect(function () {
            chart.setOption(makeOption({ data: [10], step: 'middle', area: true }), true);
        }).not.toThrow();
        expect(getPolyShape(chart, 'ec-polyline').points.length).toEqual(2);

        expect(function () {
            chart.setOption(makeOption({ data: [], step: 'middle', area: true }), true);
        }).not.toThrow();
    });

    it('should reuse the buffers of the stacked base line without mixing the items up', function () {
        chart.setOption({
            animation: false,
            xAxis: { type: 'category', data: ['a', 'b', 'c', 'd'] },
            yAxis: { type: 'value' },
            series: [{
                type: 'line',
                stack: 'total',
                areaStyle: {},
                data: [10, 20, 30, 40]
            }, {
                type: 'line',
                stack: 'total',
                areaStyle: {},
                data: [5, 5, 5, 5]
            }]
        });

        const els = getGraphicElements(chart, 'series', 1);
        let stackedOnPoints: ArrayLike<number>;
        for (let i = 0; i < els.length; i++) {
            if (els[i].type === 'ec-polygon') {
                stackedOnPoints = (els[i] as any).shape.stackedOnPoints;
            }
        }
        expect(stackedOnPoints).toBeTruthy();

        // The base line of the second series is the first series, so every base
        // point has to differ from its neighbours. A shared buffer that is stored
        // by reference instead of by value would make them all the same.
        const ys: number[] = [];
        for (let i = 0; i < stackedOnPoints.length; i += 2) {
            ys.push(stackedOnPoints[i + 1]);
        }
        expect(ys.length).toEqual(4);
        for (let i = 1; i < ys.length; i++) {
            expect(ys[i]).toBeLessThan(ys[i - 1]);
        }
    });

    it('should keep updating the shape across renders', function () {
        chart.setOption(makeOption({ data: [10, 20, 30, 40, 50], step: 'start' }));
        const before = Array.prototype.slice.call(getPolyShape(chart, 'ec-polyline').points);

        chart.setOption(makeOption({ data: [50, 40, 30, 20, 10], step: 'start' }));
        const after = Array.prototype.slice.call(getPolyShape(chart, 'ec-polyline').points);

        expect(after.length).toEqual(before.length);
        expect(after).not.toEqual(before);
    });

    it('should not break when animation is switched on after being off', function () {
        chart.setOption(makeOption({ data: [10, 20, 30, 40, 50], step: 'middle', area: true }));
        expect(function () {
            chart.setOption(makeOption({
                data: [50, 40, 30, 20, 10], step: 'middle', area: true, animation: true
            }));
        }).not.toThrow();
    });
});

