function listCacheGet<T>(cache: InnerTickLabelCache<T>, key: CacheKey, scaleExtent: number[]): T {
    for (let i = 0; i < cache.length; i++) {
        if (cache[i].key === key
            && cache[i].scaleExtent0 === scaleExtent[0]
            && cache[i].scaleExtent1 === scaleExtent[1]
        ) {
            return cache[i].value;
        }
    }
}

function listCacheSet<T>(cache: InnerTickLabelCache<T>, key: CacheKey, scaleExtent: number[], value: T): T {
    const item = {
        key: key,
        value: value,
        scaleExtent0: scaleExtent[0],
        scaleExtent1: scaleExtent[1]
    };
    for (let i = 0; i < cache.length; i++) {
        // Replace the outdated result of the same key rather than piling them up.
        if (cache[i].key === key) {
            cache[i] = item;
            return value;
        }
    }
    cache.push(item);
    return value;
}

