dataToPoint(data: ScaleDataValue[], clamp?: boolean, out?: number[]): number[] {
    out = out || [];
    const xVal = data[0];
    const yVal = data[1];
    // Fast path
    if (this._transform
        // It's supported that if data is like `[Inifity, 123]`, where only Y pixel calculated.
        && xVal != null
